import json,hashlib,math
from pathlib import Path
O=Path(__file__).resolve().parent;R=O.parent;GAME=R.parents[4]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def project(x,y,z):return [224+128*x,256-128*y-89.6*z]
old=['initial.json','proposedcriteria.json','source-contract-proposal.json','interface-correction-options.json','raw-evidence-manifest.json']
sourceInputs=[R/'contract-measurements.json',R/'native-inspection.json',GAME/'wireframe/sprite-layout.js',GAME/'wireframe/world-sprite-raster.js',R.parents[1]/'dock-entry/reviews/own-consumer-order.json']
# Coordinates are a mathematical interface specification; no native candidate geometry is constructed.
records=[]
for d,a in [('S',0),('E',math.pi/2),('N',math.pi),('W',-math.pi/2)]:
 def world(p):
  x,y,z=p;y-=1.5
  return [math.cos(a)*x-math.sin(a)*y,math.sin(a)*x+math.cos(a)*y,z]
 line=[project(*world((x,0,.22))) for x in [-.5,0,.5]]
 # Worst shallow exterior post location, y=0, capheight=.49. Extent farther exterior only makes N cap more exterior.
 cap=project(*world((0,0,.49)))
 terminal=project(*world((0,0,.22)))
 records.append({'facing':d,'floorContactLogicalPixels':line,'entryContactLogicalPixels':line,'maximumCapHeightAtContactProjected':cap,'capMinusTerminalPixels':[cap[i]-terminal[i] for i in range(2)],'currentConsumerOrder':['dock-entry','dock-floor'] if d=='N' else ['dock-floor','dock-entry'],'geometricReason':{'S':'All entry solids are exterior/closer to camera than floor. The entry may project over the deck because of height; entry-over-floor is the correct object ordering.','N':'All entry solids are exterior/farther from camera than floor. A cap at or above z0.22 projects at or outside the rear deck frontier; lower hidden base portions may be correctly occluded. Place caps wholly exterior in world space, not the old inboard halfcell.','E':'Entry and deck occupy opposite sides of a common screen-x boundary; height does not change screen x. Side-by-side projected bounds remove whole-object painter conflict.','W':'Entry and deck occupy opposite sides of a common screen-x boundary; height does not change screen x. Side-by-side projected bounds remove whole-object painter conflict.'}[d]})
report={'scope':'Technical reconciliation math only; not a candidate/native render or visual approval','unchangedOriginalReviewHashes':[{'path':n,'sha256':sha(R/n)} for n in old],'sourceInputs':[{'path':str(p),'sha256':sha(p)} for p in sourceInputs],'registeredProjection':{'basisLogical':{'X':[128,0],'Y':[0,-128],'Z':[0,-89.6]},'root':[224,256],'sourceScale':2},'sharedContact':{'entryLocalPlane':'y=0,z=0.22','entryRelativeRootInFloorSpace':[0,-1.5,0],'floorPlane':'y=-1.5,z=0.22','clearWidthMinimum':.76,'entryVisibleSolidsLocalY':[-.5,0],'floorClosureMaximumBounds':{'x':[-.5,.5],'y':[-1.5,-1.48],'z':[0,.22]},'floorClosureReason':'Measured original end bevel is0.008world: edge top0.212 at y=-1.5 returns to flat0.22 by y=-1.49. A0.02inboard band covers the existing edge bevel and gives margin for a native union into broad deck. It may also close source0.012wide plank gaps across terminal contact; no notch/globaltop change.','constructionNote':'Maximum permission box, not prescribed board or beam topology. Joining interface endpoints and flat support remain exact; editor chooses native structural method.'},'allFacingProjection':records,'numericToleranceProposal':{'rootAndContactWorldAbs':1e-5,'contactMutualMismatchWorldAbs':1e-5,'broadDeckTopAbsFrom0_22':.002,'cameraCalibrationLogicalPxAbs':.02,'floorClosureBandMaxDepth':.02,'contactWidthMin':.76,'contactToleranceProjectedXYLogicalPx':.00128,'contactToleranceProjectedZLogicalPx':.000896},'filteringRisk':{'case':'Two separately antialiased touching opaque sprites, edge alpha a and1-a','sourceOverUnionAlphaFormula':'1-(1-a)*a','minimumUnionAlpha':.75,'atA':.5,'implication':'Exact mesh contact can still produce a background-sensitive alpha trough after independent capture/resampling. This analytic worst case is not evidence that the future capture fails or passes. Require actual native join versus independently composed atlas under real common filtering/fractional phases. No gap may be excused as inevitable without testing.'},'honestBaselineCorrection':'The original dock-floor published-entry-join-N diagnostic used a fixed entry-over-floor order, unlike current consumer N floor-over-entry. Retain it as a diagnostic, not a faithful current-N consumer render. The independently measured native submerged geometry remains valid. The new reconciliation uses actual per-facing consumer order from source.'}
(O/'analytic-evidence.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'sourceInputsBound':len(sourceInputs),'originalProposalsBound':len(old),'cameraContactRecords':len(records),'file':'analytic-evidence.json'},indent=2))
